draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character 1
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 - 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 + 15, H/2 + 40);
  ctx.stroke();

  // character 2 with flaws
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 - 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 + 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - W/4 - 10, H/2 + 60, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - W/4 + 10, H/2 + 60, 5, 0, 2 * Math.PI);
  ctx.stroke();

  // projection line
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W - W/4, H/2 + 20 + 30 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
